{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Parents must ensure participating students take all annual Tennessee comprehensive assessment program (TCAP) tests, or state-authorized successor tests, that apply to public school students in the same grade or course subject.",
      "rationale": "Conveys the parental duty, annual testing, and grade-or-course alignment, with the exemption described later. However, it does not identify § 49-10-1403(e), whose number is needed to identify the unnamed statutory program, and replaces state-board authorization with generic state authorization."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "In 11th grade, parents must ensure students take the examination required for public school students under § 49-6-6001(b)(1).",
      "rationale": "Conveys the parental duty and required eleventh-grade examination, with the exemption described later. It does not identify § 49-10-1403(e), leaving the statutory program to which this duty applies unidentified."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "For students in kindergarten through third grade, parents must ensure students take each of the three Tennessee universal reading screeners, or state-approved alternatives, during the three administration windows established by the department of education.",
      "rationale": "Conveys the parental duty, grade range, three screeners, and department-established windows. It omits annual administration, does not specify state-board approval of alternative universal reading screeners, and leaves the amended statutory program unidentified."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "Test results must be reported to the student's parent.",
      "rationale": "Conveys the reporting requirement and recipient, but does not identify § 49-10-1403(e), which establishes the statutory scope of the results subject to reporting."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Students with disabilities who would use alternate assessments according to their IEP are exempt from these requirements.",
      "rationale": "Conveys the disability exemption and IEP-based eligibility. However, it does not identify § 49-10-1403(e), leaving unclear the statutory program and subsection to which the exemption is limited."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "These assessments are also established as conditions of participating in the program.",
      "rationale": "In context, incorporates the previously described annual TCAP requirements as participation conditions. It does not identify the separate amendment to § 49-6-2606(a)(1), and the incorporated description specifies generic state authorization rather than state-board authorization of successor tests."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "These assessments are also established as conditions of participating in the program.",
      "rationale": "In context, makes the previously described eleventh-grade examination a participation condition. It does not identify § 49-6-2606(a)(1), so the statutory program governed by this separate requirement remains unidentified."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "These assessments are also established as conditions of participating in the program.",
      "rationale": "In context, incorporates the K–3 screening requirements as participation conditions. The incorporated description omits annual administration and state-board approval of alternative universal reading screeners, and the summary does not identify the affected program through § 49-6-2606(a)(1)."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the effective date accurately."
    }
  ]
}
